#include <stdio.h>
#include <stdlib.h>

int main(void) {
char source[3]={'a',' ','b'};
char buffer[4]; int length=3;
for(int i=0;i<4;i++) buffer[i]='?';
for(int i=0;i<length;i++) buffer[i]=source[i];
int end=0; while(end<4 && buffer[end]!='\0') end++;
if(end==4) puts("unterminated"); else printf("length=%d text=%s\n",end,buffer);
return 0;
}

