int main(void) {
int *owner=malloc(2*sizeof *owner); if(!owner) return 1;
owner[0]=2;owner[1]=4;
int *next=realloc(owner,4*sizeof *owner); if(!next) {free(owner);return 1;}
owner=next; owner[2]=0; owner[3]=0;
for(int i=2;i<3;i++) owner[i]=2*(i+1);
printf("%d %d %d %d\n",owner[0],owner[1],owner[2],owner[3]);
free(owner);owner=NULL;
return 0;
}

